import type { Match, Team } from "./filterBigMatches";
import realFixtures from "./fixtures.json";
import mockFixtures from "./fixtures.mock.json";

export interface Fixtures {
	matches: Match[];
	teams: Team[];
}
// Environment-scoped fixtures, selected via the VITE_FIXTURES build env var:
// - development (default) / production → real data (generated by CI)
// - mock → src/lib/fixtures.mock.json (test-only; set by e2e/run.mjs)
// Both files are imported statically so bundlers/tsc see them; the unused one is
// tree-shaken per build.
export function loadFixtures(): Fixtures {
	const data =
		import.meta.env.VITE_FIXTURES === "mock" ? mockFixtures : realFixtures;
	const matches = data.matches as Match[];
	const shortNames = new Map<number, string>();
	for (const m of matches) {
		if (m.homeTeam.shortName)
			shortNames.set(m.homeTeam.id, m.homeTeam.shortName);
		if (m.awayTeam.shortName)
			shortNames.set(m.awayTeam.id, m.awayTeam.shortName);
	}
	const rawTeams = data.teams as Team[];
	const teams: Team[] = rawTeams.map((t) => ({
		...t,
		shortName: t.shortName ?? shortNames.get(t.id),
	}));
	return { matches, teams };
}
export function loadFixturesOrThrow(): Fixtures {
	const fixtures = loadFixtures();
	if (fixtures.teams.length === 0 || fixtures.matches.length === 0) {
		throw new Error(
			"App data missing — run `source .env && npm run data:gen` then restart.",
		);
	}
	return fixtures;
}
